pub fn rotate_by(angle: f32) {
    let a = angle;
    unsafe {
        let old_dir_x = DIR_X;
        DIR_X = DIR_X * a.cos() - DIR_Y * a.sin();
        DIR_Y = old_dir_x * a.sin() + DIR_Y * a.cos();

        let old_plane_x = PLANE_X;
        PLANE_X = PLANE_X * a.cos() - PLANE_Y * a.sin();
        PLANE_Y = old_plane_x * a.sin() + PLANE_Y * a.cos();
    }
}

