            perfFps = 1000 / (perfMs || 1);
            perfAccumMs = 0;
            perfFrameCount = 0;
        }

        ensureViews();
        ctx.putImageData(img, 0, 0);

        // update and draw map overlay
        try { drawMapOverlay(); } catch (e) { /* non-fatal */ }

