        ctx.save();
        ctx.fillStyle = "rgba(0,0,0,0.45)";
        ctx.fillRect(4, 4, 120, 20);
        ctx.fillStyle = "#0f0";
        ctx.font = "12px monospace";
        const txt = `${perfFps.toFixed(1)} fps ${perfMs.toFixed(1)} ms`;
        ctx.fillText(txt, 8, 18);
        ctx.restore();

        requestAnimationFrame(frame);
    }

    frame();
})();

