          for (let x = 0; x < mapW; x++) row += mapView[y * mapW + x] === 1 ? '#' : '.';
          rows.push(row);
        }
        try { const px = pkg.get_pos_x(); const py = pkg.get_pos_y(); console.log(`player @ ${px.toFixed(2)}, ${py.toFixed(2)}`); } catch (e) {}
        console.log(rows.join('\n'));
      } catch (e) { console.error('printMap failed', e); }
    };

    // animation frame
    let perfFrameCount = 0, perfAccumMs = 0, perfMs = 0, perfFps = 0;

    function frame() {
      const now = performance.now();
      let dt = (now - lastFrameTime) / 1000;
      if (!isFinite(dt) || dt <= 0) dt = 1 / 60;
      if (dt > 0.1) dt = 0.1;
      lastFrameTime = now;

      const t0 = performance.now();
      pkg.step(forward, turn, strafe, jump, dt);
      const t1 = performance.now();
      const dur = t1 - t0;

      perfAccumMs += dur; perfFrameCount++;
      if (perfFrameCount >= 30) { perfMs = perfAccumMs / perfFrameCount; perfFps = 1000 / (perfMs || 1); perfAccumMs = 0; perfFrameCount = 0; }

      ensureViews(w, h);
      ctx.putImageData(img, 0, 0);
      drawMapOverlay();

      // small overlay
      ctx.save(); ctx.fillStyle = 'rgba(0,0,0,0.45)'; ctx.fillRect(4,4,120,20); ctx.fillStyle = '#0f0'; ctx.font = '12px monospace'; const txt = `${perfFps.toFixed(1)} fps ${perfMs.toFixed(1)} ms`; ctx.fillText(txt,8,18); ctx.restore();

      raf = requestAnimationFrame(frame);
    }

    raf = requestAnimationFrame(frame);

    onDestroy(() => {
      if (raf) cancelAnimationFrame(raf);
      unbind();
    });
  });
</script>

