      const j = await r.json();
      parts.push(...j);
    } catch (e) {
      // ignore
    }
  }
  if (parts.length === 0) {
    tracesText = 'no traces available';
    return;
  }

  const maxTs = Math.max(...parts.map(p => p.timestamp_ms || 0));
  const windowStart = Math.max(0, maxTs - 20000);
  const recent = parts.filter(p => (p.timestamp_ms || 0) >= windowStart);
  tracesText = JSON.stringify(recent, null, 2);
}

function regenFromInput() {
  if (!pkg) return;
  const seed = Number(seedInput) || 0;
  try {
    pkg.regenerate_map(seed);
    lastSeed.set(seed);
  } catch (e) {
    console.error('regenerate_map failed', e);
  }
}

function regenWithSize() {
  const w = Number(widthInput) || 0;
  const h = Number(heightInput) || 0;
  const seed = Number(seedInput) || 0;
  if (!pkg) return;
  try {
    if (typeof pkg.regenerate_map_with_size === 'function') {
      pkg.regenerate_map_with_size(w, h, seed);
    } else {
      pkg.regenerate_map(seed);
      setTimeout(() => {
        try {
          const mw = pkg.get_map_w();
          const mh = pkg.get_map_h();
          console.log('map size after regen:', mw, mh);
        } catch (e) {}
      }, 50);
    }
    lastSeed.set(seed);
  } catch (e) {
    console.error('regen failed', e);
  }
}

onMount(() => {
  loadTraces();
  const iv = setInterval(loadTraces, 5000);
  return () => { clearInterval(iv); };
});
</script>

