                      5.0 * std::f32::consts::PI / 4.0, 3.0 * std::f32::consts::PI / 2.0,
                      7.0 * std::f32::consts::PI / 4.0];

        // Test center
        if map_at(x as i32, y as i32) != 0 {
            return false;
        }

        // Test points on circle perimeter
        for &angle in &angles {
            let test_x = x + radius * angle.cos();
            let test_y = y + radius * angle.sin();
            if map_at(test_x as i32, test_y as i32) != 0 {
                return false;
            }
        }
        true
